    onSelect: function() {
        var me = this,
            vm = me.getViewModel(),
            store = me.getStore('ApprovalBoxStore'),
            refs = me.getReferences(),
            command = vm.get('command'),
            dpDvcdNm = null,
            selectCnt = vm.get('selectCnt'),
            tglSanMode = refs.tglSanMode;	// 일괄결재 모드 토글

        // 부서완료함일 경우 부서구분명을 추가한다.
        if(command == '97'){
            dpDvcdNm = '부서';
        }

        // 검색조건 설정후 1페이지부터 조회
        store.getProxy().extraParams = {
            command 	: command,
            searchYear 	: vm.get('searchYear'),
            vwId    	: vm.get('vwId'),
            rqprId  	: vm.get('rqprId'),
            docNo   	: vm.get('docNo'),
            dpDvcdNm	: dpDvcdNm
        };
        store.removeAll();
        store.loadPage(1);

        // (일괄결재)선택된 문서 개수 초기화
        vm.set('selectCnt', 0);

        // 미결함, 담당부서함인 경우 일괄결재 모드 툴바 활성화
        if(command == Constants.sanction.PENDING_BOX || command == Constants.sanction.RECEIPT_BOX){
            tglSanMode.setHidden(false);
        }

        // 문서 제목 최대길이 동적 설정
        me.setTitleWidth();
    },

    /* 조회버튼(기존) */
    oldOnBtnSearchTap: function(button, e, eOpts) {
        var me = this,
            searchYear = me.getViewModel().get('searchYear');
            searchVwIdStore = me.getViewModel().storeInfo.SearchVwIdStore; // 검색조건 : 결재문서명 데이터
        // 팝업창 생성 및 데이터전달
        var win = Ext.create('BNK.view.Budget.exp.ExpNteApr03M', {
            searchYear : searchYear,
            searchVwIdStore : searchVwIdStore
        });
        // 팝업창에서 이벤트 호출시 실행되는 함수
        me.mon(win, 'search', function(data, popup) {
            var me = this,
                vm = me.getViewModel(),
                vwNm = '전체문서';

            // 팝업창 닫기
            popup.close();

            // 결재문서명
            if (data.vwId) {
                var items = vm.storeInfo.SearchVwIdStore.getData().items;
                for (var i in items) {
                    var item = items[i].data;
                    if (data.vwId === item.value) {
                        vwNm = item.text;
                        break;
                    }
                }
            }

            vm.set('searchYear', data.searchYear);	// 기준연도
            vm.set('vwId', data.vwId);	   			// 결재문서아이디
            vm.set('vwNm', vwNm);		   			// 결재문서명
            vm.set('rqprId', data.rqprId); 			// 사번

            me.onSelect(); // 조회
        }, me);

        win.show(); // 팝업창표시
    },

    /* 해상도에 맞게 툴바 문서 제목 최대길이 변경하기 */
    setTitleWidth: function() {
        var me = this,
            refs = me.getReferences(),
            tbrLbExpTitle = refs.tbrLbExpTitle;

        // 현재 화면의 해상도 가져오기
        var viewSize = Ext.getBody().getViewSize();
        var width = viewSize.width;
        var rWidth = 0;

        if(width != undefined && width > 0){
            rWidth = width - 120;
        }

        var style = "max-width:" + rWidth + "px;";

        // 제목 스타일 설정
        tbrLbExpTitle.setStyle(style);
    },

    /* 그리드 체크박스(일괄결재를 위한 row 선택) 이벤트 */
    onCbxChange: function(checkcell, rowIndex, checked, record, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            cellChecked = checkcell.getValue(),
            selectCnt = vm.get('selectCnt'),
            aprHistId = record.id,
            vwId = record.data.vwId;

        // 모바일 결재여부판단 (mobYn)
        if(record.data.mobYn == 'N') {
            Ext.Msg.alert('알림', '해당 문서는 모바일에서 결재할 수 없습니다.');
            return;
        }

        // 일괄결재 가능한 최대 개수 확인
        if(selectCnt == 10 && !cellChecked == true){
            Ext.Msg.alert('알림', '일괄결재는 최대 10건까지 가능합니다.');
            return;
        }

        // 세금계산서, 여비정산서는 모바일에서 결재불가. 해당 경우 제외하기
        if(vwId == 'BgxNfmAply71'){
            Ext.Ajax.request({
                headers : {
                    serviceId : 'COMAPR0001R04M'
                },
                jsonData:{
                    aprHistId : aprHistId
                },
                success : function(response, scope) {
                    var res = Ext.JSON.decode(Ext.JSON.decode(response.responseText).result);
                    var aplKndCd = res.docData.afterchange.applyInfo.aplKndcd;

                    if(aplKndCd == Constants.aplKndcd.TXINV || aplKndCd == Constants.aplKndcd.XPNS){ // 세금계산서, 여비정산서인 경우
                        Ext.Msg.alert('알림', '해당 문서는 모바일에서 결재할 수 없습니다.');
                        return;
                    }

                    // 체크박스 체크 처리
                    checkcell.setValue(!cellChecked);
                    // 체크된 record 상태값 처리
                    record.set('checked', !cellChecked);

                    // 선택문서 개수 처리
                    if(cellChecked){
                        vm.set('selectCnt', selectCnt - 1);
                    }else{
                        vm.set('selectCnt', selectCnt + 1);
                    }
                },
                failure : function(response){
                    Ext.Msg.alert('오류', '결재 정보를 가져오는데 실패했습니다.');
                    return;
                }
            });
        }else{
            // 체크박스 체크 처리
            checkcell.setValue(!cellChecked);
            // 체크된 record 상태값 처리
            record.set('checked', !cellChecked);

            // 선택문서 개수 처리
            if(cellChecked){
                vm.set('selectCnt', selectCnt - 1);
            }else{
                vm.set('selectCnt', selectCnt + 1);
            }
        }
    },

